def stripes_diag(g):
    # collect (d,color) for diagonal stripes slope1
    cons={}
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]: cons.setdefault((r-c)%100000, set()).add(g[r][c])
    return cons
def solve_diag(g,H,W):
    cons={}
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]: cons.setdefault(r-c,set()).add(g[r][c])
    for p in range(2,30):
        P={}
        ok=True
        for d,cols in cons.items():
            res=d%p
            for col in cols:
                if res in P and P[res]!=col: ok=False;break
                P[res]=col
            if not ok: break
        if ok and len(P)==p:
            return [[P[(r-c)%p] for c in range(W)] for r in range(H)],p
    return None,None

o,p=solve_diag(GG['Demo pair 2 input'],24,24)
print('demo2 p=',p,'match:',o==GG['Demo pair 2 output'])
