                res = d % p
                for col in cols:
                    if res in P and P[res] != col:
                        ok = False
                        break
                    P[res] = col
                if not ok:
                    break
            if ok and len(P) == p:
                return [[P[(r - c) % p] for c in range(W)] for r in range(H)]
        return None
    # try diagonal stripes (slope 1): coordinate r-c
    cons = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c]:
                cons.setdefault(r - c, set()).add(grid[r][c])
    out = solve(cons, H, W)
    if out is not None:
        return out
    # horizontal bars: coordinate r
    cons = {}
    for r in range(H):
        cols = set(x for x in grid[r] if x)
        if cols:
            cons[r] = cols
    for p in range(2, 30):
